{"command": "cat > /tmp/vis.py <<'PYEOF'
import sys,re
data=sys.stdin.read()
lines=data.split('\n')
NAMES={0:'K',1:'r',2:'g',3:'y',4:'b',5:'m',6:'c',7:'w',15:'W'}
for ln,line in enumerate(lines):
    out=[];cur=''
    i=0
    while i<len(line):
        m=re.match(r'\x1b\[([0-9;]*)m',line[i:])
        if m:
            code=m.group(1);i+=m.end()
            if code.startswith('38;5;'):
                cur=NAMES.get(code[5:],code[5:])
            elif code in ('0','00'):
                cur=''
            elif code=='1':
                cur+='#'  # bold marker
            elif code=='2':
                cur+='d'  # dim
            elif code=='3':
                cur+='i'  # italic
            elif code in ('4',):
                cur+='u'
            elif code in ('7',):
                cur+='R'
            elif code.startswith('39'):
                pass
            else:
                cur='?'+code
            continue
        out.append((cur,line[i]))
        i+=1
    s=''.join(c if c=='' else f'[{c}]' for _,c in out)
    s=s+('|'+''.join(f'<{c}>' for c,_ in out))
    print(f'{ln:02d} '+s)
PYEOF
tmux capture-pane -t s1 -p -e | python3 /tmp/vis.py | cut -c1-200 | head -12"}

