def wraplen(text, width):
    words=text.split(' ')
    # ratatui-like: build lines, each word separated by a single space, stop when adding the next word would exceed width
    cur=0; out=''
    for w in words:
        add = len(w) if cur==0 else 1+len(w)
        if cur+add <= width:
            out += (' ' if cur else '')+w; cur+=add
        else: break
    return len(out)
texts={
 'search':'Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>',
