package main

import (
	"fmt"
	"os"
	"syscall"
	"unsafe"
)

// Terminal handling: raw mode, size, input and output.
// Uses only the standard library (syscall) — no external dependencies.

func ioctlPtr(fd int, req uintptr, arg uintptr) error {
	_, _, e := syscall.Syscall(syscall.SYS_IOCTL, uintptr(fd), req, arg)
	if e != 0 {
		return e
	}
	return nil
}

func isTTY(fd int) bool {
	var t syscall.Termios
	return ioctlPtr(fd, syscall.TCGETS, uintptr(unsafe.Pointer(&t))) == nil
}

// Terminal wraps the input/output file descriptors.
type Terminal struct {
