		codes = append(codes, "1")
	}
	if cur.Cross && !prev.Cross {
		codes = append(codes, "9")
	}
	return codes
}

func (s *Screen) writeStr(str string) { s.term.Write([]byte(str)) }

// Draw flushes the buffer contents to the terminal, writing only the changes.
func (s *Screen) Draw(cursor *CursorPos) {
	var sb strings.Builder
	lastX, lastY := -1, -1
	for y := 0; y < s.buf.H; y++ {
		for x := 0; x < s.buf.W; x++ {
			c := s.buf.Cells[y*s.buf.W+x]
			p := s.prev.Cells[y*s.buf.W+x]
			if c == p {
				continue
			}
			if x != lastX+1 || y != lastY {
				fmt.Fprintf(&sb, "\x1b[%d;%dH", y+1, x+1)
			}
			if !c.St.Eq(s.style) {
				codes := modCodes(s.style, c.St)
				if len(codes) > 0 {
					sb.WriteString("\x1b[")
					sb.WriteString(strings.Join(codes, ";"))
					sb.WriteString("m")
				}
				sb.WriteString("\x1b[")
				sb.WriteString(fgPart(c.St.Fg))
				sb.WriteString(";")
				sb.WriteString(bgPart(c.St.Bg))
				sb.WriteString("m")
				s.style = c.St
			}
			sb.WriteRune(c.Ch)
			lastX, lastY = x, y
			s.prev.Cells[y*s.buf.W+x] = c
		}
	}
	sb.WriteString("\x1b[39m\x1b[49m\x1b[59m\x1b[0m")
	if cursor == nil {
		sb.WriteString("\x1b[?25l")
	} else {
		fmt.Fprintf(&sb, "\x1b[?25h\x1b[%d;%dH", cursor.Y+1, cursor.X+1)
	}
	s.writeStr(sb.String())
}

// EnterAltScreen switches to the alternate screen and hides the cursor.
func (s *Screen) EnterAltScreen() { s.writeStr("\x1b[?1049h\x1b[?25l") }

// LeaveAltScreen returns to the main screen and shows the cursor.
func (s *Screen) LeaveAltScreen() {
	s.writeStr("\x1b[39m\x1b[49m\x1b[59m\x1b[0m\x1b[?1049l\x1b[?25h")
}

// Block describes a bordered box.
type Block struct {
	Title  string
	Tabs   []string
	TabIdx int
	Right  string
	Style  Style
}

// DrawBlock renders a block (borders + titles) into the buffer.
func (b *Buffer) DrawBlock(a Area, blk Block) {
	st := blk.Style
	if a.W < 2 || a.H < 2 {
		return
	}
	b.set(a.X, a.Y, '╭', st)
	b.set(a.Right()-1, a.Y, '╮', st)
	b.set(a.X, a.Bottom()-1, '╰', st)
	b.set(a.Right()-1, a.Bottom()-1, '╯', st)
	for x := a.X + 1; x < a.Right()-1; x++ {
		b.set(x, a.Y, '─', st)
		b.set(x, a.Bottom()-1, '─', st)
	}
	for y := a.Y + 1; y < a.Bottom()-1; y++ {
		b.set(a.X, y, '│', st)
		b.set(a.Right()-1, y, '│', st)
	}
	inner := a.Inner()
	if len(blk.Right) > 0 {
		runes := []rune(blk.Right)
		start := inner.Right() - len(runes)
		for i, r := range runes {
			b.set(start+i, a.Y, r, st)
		}
	}
	if len(blk.Tabs) > 0 && blk.TabIdx < len(blk.Tabs) {
		txt := "[" + blk.Tabs[blk.TabIdx] + "]"
		runes := []rune(txt)
		start := inner.Right() - len(runes)
		for i, r := range runes {
			b.set(start+i, a.Y, r, st)
		}
	}
	if blk.Title != "" {
		runes := []rune(blk.Title)
		for i, r := range runes {
			if i >= inner.W {
				break
			}
			b.set(inner.X+i, a.Y, r, st)
		}
	}
}

// WriteRunes writes a string of runes into the buffer at (x,y) with clipping.
func (b *Buffer) WriteRunes(x, y int, txt string, st Style) int {
	runes := []rune(txt)
	n := 0
	for i, r := range runes {
		if x+i >= b.W {
			break
		}
		b.set(x+i, y, r, st)
		n++
	}
	return n
}
GOEOF
