	"unicode"
)

// Search modes for the search field.
const (
	SearchSimple = iota
	SearchMatchCase
	SearchWholeWord
	SearchCaseWholeWord
	SearchRegex
)

var searchModeNames = []string{"Simple", "Match Case", "Match Whole Word", "Match Case Whole Word", "Regex"}

// Replace modes for the replace field.
const (
	ReplaceSimple = iota
	ReplacePreserveCase
	ReplaceDeleteLine
)

var replaceModeNames = []string{"Simple", "Preserve Case", "Delete Line"}

// MaxFiles is the number of files above which the app shows the "large folder"
// notification instead of searching automatically.
const MaxFiles = 1000

// Match is a single occurrence of the search pattern inside a file.
type Match struct {
	Line  int   // 0-based line index
	Start int   // byte offset within the line
	End   int   // byte offset (exclusive) within the line
}

// FileResult holds the search results for one file.
type FileResult struct {
	Path    string   // display path
	Lines   []string // file lines at search time
	Matches []Match
	Count   int
	Deleted bool // removed from the replacement process via 'd'
}

// Matcher finds all occurrences of the pattern in a line.
type Matcher struct {
	Mode    int
	Text    string
	Lower   string
	Re      *regexp.Regexp
	IsValid bool
}

func NewMatcher(mode int, text string) *Matcher {
	m := &Matcher{Mode: mode, Text: text}
	if mode == SearchSimple || mode == SearchWholeWord {
		m.Lower = strings.ToLower(text)
	}
	if mode == SearchRegex && text != "" {
		re, err := regexp.Compile(text)
		if err == nil {
			m.Re = re
			m.IsValid = true
		}
	}
	return m
}

// IsEmpty reports whether the pattern can never match.
func (m *Matcher) IsEmpty() bool {
	if m.Text == "" {
		return true
	}
	if m.Mode == SearchRegex {
		return !m.IsValid
	}
	return false
}

func isWordChar(r rune) bool {
	return unicode.IsLetter(r) || unicode.IsDigit(r) || r == '_'
}

func (m *Matcher) FindAll(line string) []Match {
	if m.IsEmpty() {
		return nil
	}
	var out []Match
	switch m.Mode {
	case SearchSimple:
		low := strings.ToLower(line)
		pat := m.Lower
		off := 0
		for {
			i := strings.Index(low[off:], pat)
			if i < 0 {
				break
			}
			start := off + i
			end := start + len(pat)
			out = append(out, Match{Start: start, End: end})
			off = end
			if off >= len(low) {
				break
			}
		}
	case SearchMatchCase:
		pat := m.Text
		off := 0
		for {
			i := strings.Index(line[off:], pat)
			if i < 0 {
				break
			}
			start := off + i
			end := start + len(pat)
			out = append(out, Match{Start: start, End: end})
			off = end
			if off >= len(line) {
				break
			}
		}
	case SearchWholeWord:
		low := strings.ToLower(line)
		pat := m.Lower
		off := 0
		for {
			i := strings.Index(low[off:], pat)
			if i < 0 {
				break
			}
			start := off + i
			end := start + len(pat)
			if isWordBoundary(low, start, end) {
				out = append(out, Match{Start: start, End: end})
			}
			off = start + 1
			if off > len(low) {
				break
			}
		}
	case SearchCaseWholeWord:
		pat := m.Text
		off := 0
		for {
			i := strings.Index(line[off:], pat)
			if i < 0 {
				break
			}
			start := off + i
			end := start + len(pat)
			if isWordBoundary(line, start, end) {
				out = append(out, Match{Start: start, End: end})
			}
			off = start + 1
			if off > len(line) {
				break
			}
		}
	case SearchRegex:
		if m.Re == nil {
			return nil
		}
		for _, loc := range m.Re.FindAllStringIndex(line, -1) {
			out = append(out, Match{Start: loc[0], End: loc[1]})
		}
	}
	return out
}

func isWordBoundary(s string, start, end int) bool {
	rs := []rune(s)
	// convert byte offsets to rune offsets
	rStart, rEnd := 0, 0
	{
		b := 0
		i := 0
		for i < len(rs) {
			if b == start {
				rStart = i
			}
			b += len(string(rs[i]))
			i++
			if b == end {
				rEnd = i
			}
		}
	}
	if rStart > 0 && isWordChar(rs[rStart-1]) {
		return false
	}
	if rEnd < len(rs) && isWordChar(rs[rEnd]) {
		return false
	}
	return true
}

// preserveCase adjusts the replacement text to the case pattern of the match.
func preserveCase(matched, repl string) string {
	if repl == "" {
		return repl
	}
	allUpper := true
	allLower := true
	hasLetter := false
	for _, r := range matched {
		if unicode.IsLetter(r) {
			hasLetter = true
			if !unicode.IsUpper(r) {
				allUpper = false
			}
			if !unicode.IsLower(r) {
				allLower = false
			}
		}
	}
	if hasLetter && allUpper {
		return strings.ToUpper(repl)
	}
	if hasLetter && allLower {
		return strings.ToLower(repl)
	}
	runes := []rune(matched)
	if len(runes) > 0 && unicode.IsUpper(runes[0]) {
		rr := []rune(repl)
		for i := range rr {
			rr[i] = unicode.ToLower(rr[i])
		}
		if len(rr) > 0 {
			rr[0] = unicode.ToUpper(rr[0])
		}
		return string(rr)
	}
	return strings.ToLower(repl)
}

// ApplyReplacement produces the new content for a file given a set of line changes.
func ApplyReplacement(lines []string, mode int, search string, repl string, match *Match, all bool) []string {
	out := make([]string, len(lines))
	copy(out, lines)
	if mode == ReplaceDeleteLine {
		if match != nil {
			idx := match.Line
			res := make([]string, 0, len(out)-1)
			for i, l := range out {
				if i == idx {
					continue
				}
				res = append(res, l)
			}
			return res
		}
		if all {
			res := []string{}
			for _, l := range out {
				if len(NewMatcher(0, search).FindAll(l)) > 0 {
					continue
				}
				res = append(res, l)
			}
			return res
		}
		return out
	}
	if all {
		m := NewMatcher(0, search)
		for i := range out {
			out[i] = replaceInLine(out[i], m, mode, repl)
		}
		return out
	}
	if match != nil && match.Line < len(out) {
		l := out[match.Line]
		m := NewMatcher(0, search)
		out[match.Line] = replaceOne(l, m, mode, repl, match.Start, match.End)
	}
	return out
}

func replaceInLine(line string, m *Matcher, mode int, repl string) string {
	matches := m.FindAll(line)
	if len(matches) == 0 {
		return line
	}
	var sb strings.Builder
	last := 0
	for _, mt := range matches {
		sb.WriteString(line[last:mt.Start])
		sb.WriteString(replText(line[mt.Start:mt.End], mode, repl))
		last = mt.End
	}
	sb.WriteString(line[last:])
	return sb.String()
}

func replaceOne(line string, m *Matcher, mode int, repl string, start, end int) string {
	matches := m.FindAll(line)
	for _, mt := range matches {
		if mt.Start == start && mt.End == end {
			return line[:mt.Start] + replText(line[mt.Start:mt.End], mode, repl) + line[mt.End:]
		}
	}
	return line
}

func replText(matched string, mode int, repl string) string {
	if mode == ReplacePreserveCase {
		return preserveCase(matched, repl)
	}
	return repl
}

// ignoreRules holds compiled ignore patterns for a directory.
type ignoreRules struct {
	patterns []ignorePattern
}

type ignorePattern struct {
	negate   bool
	dirOnly  bool
	anchored bool
	segments []string
	raw      string
}

func parseIgnoreLine(line string) (ignorePattern, bool) {
	s := strings.TrimRight(line, " \t\r")
	if s == "" || strings.HasPrefix(s, "#") {
		return ignorePattern{}, false
	}
	var p ignorePattern
	if strings.HasPrefix(s, "!") {
		p.negate = true
		s = s[1:]
	}
	if strings.HasSuffix(s, "/") {
		p.dirOnly = true
		s = strings.TrimSuffix(s, "/")
	}
	if strings.HasPrefix(s, "/") {
		p.anchored = true
		s = s[1:]
	}
	s = strings.TrimPrefix(s, "./")
	if s == "" {
		return ignorePattern{}, false
	}
	p.raw = s
	p.segments = strings.Split(s, "/")
	return p, true
}

// matchPath reports whether the relative path (slash separated) matches the pattern.
func (p ignorePattern) matches(rel string, isDir bool) bool {
	if p.dirOnly && !isDir {
		return false
	}
	segs := strings.Split(rel, "/")
	if p.anchored {
		return matchSegments(p.segments, segs)
	}
	if len(p.segments) > 1 {
		// relative to the ignore file's directory
		return matchSegments(p.segments, segs)
	}
	// match any path component
	for _, s := range segs {
		if ok, _ := filepath.Match(p.segments[0], s); ok {
			return true
		}
	}
	return false
}

func matchSegments(pat, segs []string) bool {
	if len(pat) > len(segs) {
		return false
	}
	for i := range pat {
		if i == len(pat)-1 {
			// the last segment may match a directory prefix
			if ok, _ := filepath.Match(pat[i], segs[i]); ok {
				return true
			}
			if i < len(segs)-1 {
				continue
			}
			return false
		}
		if ok, _ := filepath.Match(pat[i], segs[i]); !ok {
			return false
		}
	}
	return true
}

// Walker collects the files below root honouring ignore rules and hidden files.
type Walker struct {
	Root        string
	Files       []string
	inGit       bool
	parentRules []ignoreRules
}

func hasGitMarker(dir string) bool {
	if _, err := os.Stat(filepath.Join(dir, ".git")); err == nil {
		return true
	}
	return false
}

func loadRules(dir string, inGit bool) ignoreRules {
	var r ignoreRules
	names := []string{".ignore"}
	if inGit {
		names = append(names, ".gitignore")
	}
	for _, n := range names {
		data, err := os.ReadFile(filepath.Join(dir, n))
		if err != nil {
			continue
		}
		for _, line := range strings.Split(string(data), "\n") {
			if p, ok := parseIgnoreLine(line); ok {
				r.patterns = append(r.patterns, p)
			}
		}
	}
	return r
}

// Walk collects the files to search.
func Walk(root string) ([]string, bool) {
	w := &Walker{Root: root}
	w.inGit = hasGitMarker(root)
	// parent ignore files
	var parents []ignoreRules
	abs, err := filepath.Abs(root)
	if err == nil {
		abs = filepath.Clean(abs)
		parts := strings.Split(abs, string(filepath.Separator))
		// walk up collecting ignore rules from ancestors
		cur := ""
		for i := 1; i < len(parts); i++ {
			cur = strings.Join(parts[:i+1], string(filepath.Separator))
			if i < len(parts)-1 {
				parents = append(parents, loadRules(cur, hasGitMarker(cur)))
			}
		}
	}
	w.parentRules = parents
	var mu sync.Mutex
	var files []string
	w.walk(root, &files, &mu)
	sort.Strings(files)
	return files, true
}

func (w *Walker) relDisplay(path string) string {
	root := w.Root
	if !strings.HasSuffix(root, string(filepath.Separator)) {
		root = root + string(filepath.Separator)
	}
	if s, ok := strings.CutPrefix(path, root); ok {
		return s
	}
	return path
}

func (w *Walker) walk(dir string, files *[]string, mu *sync.Mutex) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	// readdir order
	for _, e := range entries {
		name := e.Name()
		if strings.HasPrefix(name, ".") {
			continue
		}
		full := filepath.Join(dir, name)
		rel, err := filepath.Rel(w.Root, full)
		if err != nil {
			rel = name
		}
		rel = filepath.ToSlash(rel)
		isDir := e.IsDir()
		if w.isIgnored(rel, isDir) {
			continue
		}
		if isDir {
			if !e.Type().IsDir() {
				continue
			}
			w.walk(full, files, mu)
			continue
		}
		if !e.Type().IsRegular() {
			continue
		}
		mu.Lock()
		*files = append(*files, full)
		mu.Unlock()
	}
}

func (w *Walker) isIgnored(rel string, isDir bool) bool {
	for _, r := range w.parentRules {
		for _, p := range r.patterns {
			if p.matches(rel, isDir) {
				return !p.negate
			}
		}
	}
	return false
}

// Search performs the search over the given files.
func Search(files []string, matcher *Matcher, root string) []FileResult {
	var mu sync.Mutex
	var out []FileResult
	var next int64
	nworkers := 8
	var wg sync.WaitGroup
	for i := 0; i < nworkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				mu.Lock()
				if int(next) >= len(files) {
					mu.Unlock()
					return
				}
				f := files[next]
				next++
				mu.Unlock()
				res := searchFile(f, matcher, root)
				if res != nil {
					mu.Lock()
					out = append(out, *res)
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	return out
}

func searchFile(path string, matcher *Matcher, root string) *FileResult {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	if len(data) == 0 {
		return nil
	}
	for _, b := range data {
		if b == 0 {
			return nil
		}
	}
	s := string(data)
	if !utf8Valid(s) {
		return nil
	}
	lines := strings.Split(s, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	// emulate Rust's lines(): strips a single trailing \r
	for i := range lines {
		lines[i] = strings.TrimSuffix(lines[i], "\r")
	}
	var matches []Match
	for i, l := range lines {
		for _, m := range matcher.FindAll(l) {
			m.Line = i
			matches = append(matches, m)
		}
	}
	if len(matches) == 0 {
		return nil
	}
	return &FileResult{Path: displayPath(path, root), Lines: lines, Matches: matches, Count: len(matches)}
}

func utf8Valid(s string) bool {
	for _, r := range s {
		if r == 0xFFFD {
			// could be a legit replacement char; ignore
		}
	}
	return true
}

func displayPath(path, root string) string {
	sep := string(filepath.Separator)
	prefix := root
	if !strings.HasSuffix(prefix, sep) {
		prefix = prefix + sep
	}
	if s, ok := strings.CutPrefix(path, prefix); ok {
		return s
	}
	return path
}
GOEOF
echo ok"}

