			if off >= len(line) {
				break
			}
		}
	case SearchWholeWord:
		low := strings.ToLower(line)
		pat := m.Lower
		off := 0
		for {
			i := strings.Index(low[off:], pat)
			if i < 0 {
				break
			}
			start := off + i
			end := start + len(pat)
			if isWordBoundary(low, start, end) {
				out = append(out, Match{Start: start, End: end})
			}
			off = start + 1
			if off > len(low) {
				break
			}
		}
	case SearchCaseWholeWord:
		pat := m.Text
		off := 0
		for {
			i := strings.Index(line[off:], pat)
			if i < 0 {
				break
			}
			start := off + i
			end := start + len(pat)
			if isWordBoundary(line, start, end) {
				out = append(out, Match{Start: start, End: end})
			}
			off = start + 1
			if off > len(line) {
