func isWordBoundary(s string, start, end int) bool {
	rs := []rune(s)
	// convert byte offsets to rune offsets
	rStart, rEnd := 0, 0
	{
		b := 0
		i := 0
		for i < len(rs) {
			if b == start {
				rStart = i
			}
			b += len(string(rs[i]))
			i++
			if b == end {
				rEnd = i
			}
		}
	}
	if rStart > 0 && isWordChar(rs[rStart-1]) {
		return false
	}
	if rEnd < len(rs) && isWordChar(rs[rEnd]) {
		return false
	}
	return true
