	allUpper := true
	allLower := true
	hasLetter := false
	for _, r := range matched {
		if unicode.IsLetter(r) {
			hasLetter = true
			if !unicode.IsUpper(r) {
				allUpper = false
			}
			if !unicode.IsLower(r) {
				allLower = false
			}
		}
	}
	if hasLetter && allUpper {
		return strings.ToUpper(repl)
	}
	if hasLetter && allLower {
		return strings.ToLower(repl)
	}
	runes := []rune(matched)
	if len(runes) > 0 && unicode.IsUpper(runes[0]) {
		rr := []rune(repl)
		for i := range rr {
			rr[i] = unicode.ToLower(rr[i])
		}
		if len(rr) > 0 {
			rr[0] = unicode.ToUpper(rr[0])
		}
		return string(rr)
	}
	return strings.ToLower(repl)
}

// ApplyReplacement produces the new content for a file given a set of line changes.
func ApplyReplacement(lines []string, mode int, search string, repl string, match *Match, all bool) []string {
	out := make([]string, len(lines))
	copy(out, lines)
	if mode == ReplaceDeleteLine {
		if match != nil {
			idx := match.Line
			res := make([]string, 0, len(out)-1)
			for i, l := range out {
				if i == idx {
					continue
				}
				res = append(res, l)
			}
			return res
		}
