	if _, err := os.Stat(filepath.Join(dir, ".git")); err == nil {
		return true
	}
	return false
}

func loadRules(dir string, inGit bool) ignoreRules {
	var r ignoreRules
	names := []string{".ignore"}
	if inGit {
		names = append(names, ".gitignore")
	}
	for _, n := range names {
		data, err := os.ReadFile(filepath.Join(dir, n))
		if err != nil {
			continue
		}
		for _, line := range strings.Split(string(data), "\n") {
			if p, ok := parseIgnoreLine(line); ok {
				r.patterns = append(r.patterns, p)
			}
		}
	}
	return r
}

// Walk collects the files to search.
func Walk(root string) ([]string, bool) {
	w := &Walker{Root: root}
	w.inGit = hasGitMarker(root)
	// parent ignore files
	var parents []ignoreRules
	abs, err := filepath.Abs(root)
	if err == nil {
		abs = filepath.Clean(abs)
		parts := strings.Split(abs, string(filepath.Separator))
		// walk up collecting ignore rules from ancestors
		cur := ""
		for i := 1; i < len(parts); i++ {
			cur = strings.Join(parts[:i+1], string(filepath.Separator))
			if i < len(parts)-1 {
				parents = append(parents, loadRules(cur, hasGitMarker(cur)))
			}
		}
	}
	w.parentRules = parents
	var mu sync.Mutex
	var files []string
	w.walk(root, &files, &mu)
	sort.Strings(files)
	return files, true
}

func (w *Walker) relDisplay(path string) string {
	root := w.Root
	if !strings.HasSuffix(root, string(filepath.Separator)) {
		root = root + string(filepath.Separator)
	}
	if s, ok := strings.CutPrefix(path, root); ok {
		return s
	}
	return path
}

func (w *Walker) walk(dir string, files *[]string, mu *sync.Mutex) {
	entries, err := os.ReadDir(dir)
	if err != nil {
		return
	}
	// readdir order
	for _, e := range entries {
		name := e.Name()
		if strings.HasPrefix(name, ".") {
			continue
		}
		full := filepath.Join(dir, name)
		rel, err := filepath.Rel(w.Root, full)
		if err != nil {
			rel = name
		}
		rel = filepath.ToSlash(rel)
		isDir := e.IsDir()
		if w.isIgnored(rel, isDir) {
			continue
		}
		if isDir {
			if !e.Type().IsDir() {
				continue
			}
			w.walk(full, files, mu)
			continue
		}
		if !e.Type().IsRegular() {
			continue
		}
		mu.Lock()
		*files = append(*files, full)
		mu.Unlock()
	}
}

func (w *Walker) isIgnored(rel string, isDir bool) bool {
	for _, r := range w.parentRules {
		for _, p := range r.patterns {
			if p.matches(rel, isDir) {
				return !p.negate
			}
		}
	}
	return false
}

// Search performs the search over the given files.
func Search(files []string, matcher *Matcher, root string) []FileResult {
	var mu sync.Mutex
	var out []FileResult
	var next int64
	nworkers := 8
	var wg sync.WaitGroup
	for i := 0; i < nworkers; i++ {
		wg.Add(1)
		go func() {
			defer wg.Done()
			for {
				mu.Lock()
				if int(next) >= len(files) {
					mu.Unlock()
					return
				}
				f := files[next]
				next++
				mu.Unlock()
				res := searchFile(f, matcher, root)
				if res != nil {
					mu.Lock()
					out = append(out, *res)
					mu.Unlock()
				}
			}
		}()
	}
	wg.Wait()
	return out
}

func searchFile(path string, matcher *Matcher, root string) *FileResult {
	data, err := os.ReadFile(path)
	if err != nil {
		return nil
	}
	if len(data) == 0 {
		return nil
	}
	for _, b := range data {
		if b == 0 {
			return nil
		}
	}
	s := string(data)
	if !utf8Valid(s) {
		return nil
	}
	lines := strings.Split(s, "\n")
	if len(lines) > 0 && lines[len(lines)-1] == "" {
		lines = lines[:len(lines)-1]
	}
	// emulate Rust's lines(): strips a single trailing \r
	for i := range lines {
		lines[i] = strings.TrimSuffix(lines[i], "\r")
	}
	var matches []Match
	for i, l := range lines {
		for _, m := range matcher.FindAll(l) {
			m.Line = i
			matches = append(matches, m)
		}
	}
	if len(matches) == 0 {
		return nil
	}
	return &FileResult{Path: displayPath(path, root), Lines: lines, Matches: matches, Count: len(matches)}
}

func utf8Valid(s string) bool {
	for _, r := range s {
		if r == 0xFFFD {
			// could be a legit replacement char; ignore
		}
	}
	return true
}

func displayPath(path, root string) string {
	sep := string(filepath.Separator)
	prefix := root
	if !strings.HasSuffix(prefix, sep) {
		prefix = prefix + sep
	}
	if s, ok := strings.CutPrefix(path, prefix); ok {
		return s
	}
	return path
}
