// json5Error is a syntax error with position information.
type json5Error struct {
	line, col int
	msg       string
}

func (e *json5Error) Error() string { return e.msg }

type parser struct {
	src  []rune
	pos  int
	line int
	col  int
}

func (p *parser) peek() rune {
	if p.pos >= len(p.src) {
		return 0
	}
	return p.src[p.pos]
}

func (p *parser) at(off int) rune {
	if p.pos+off >= len(p.src) {
		return 0
	}
	return p.src[p.pos+off]
}

func (p *parser) advance() rune {
	r := p.src[p.pos]
	p.pos++
	if r == '\n' {
		p.line++
		p.col = 1
	} else {
		p.col++
	}
	return r
}

func (p *parser) skipWs() {
	for p.pos < len(p.src) {
		r := p.peek()
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' || r == '\v' {
			p.advance()
			continue
		}
		if r == '/' && p.at(1) == '/' {
			for p.pos < len(p.src) && p.peek() != '\n' {
				p.advance()
			}
			continue
		}
		if r == '/' && p.at(1) == '*' {
			p.advance()
			p.advance()
			for p.pos < len(p.src) {
				if p.peek() == '*' && p.at(1) == '/' {
					p.advance()
					p.advance()
					break
				}
				p.advance()
			}
			continue
		}
		break
	}
}

func (p *parser) errAt(msg string) error {
	return &json5Error{line: p.line, col: p.col, msg: msg}
}

const expectedValue = "expected array, boolean, null, number, object, or string"

func (p *parser) parseValue() (interface{}, error) {
	p.skipWs()
	if p.pos >= len(p.src) {
		return nil, p.errAt(expectedValue)
	}
	switch r := p.peek(); {
	case r == '{':
		return p.parseObject()
	case r == '[':
		return p.parseArray()
	case r == '"' || r == '\'':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return s, nil
	case r == '-' || (r >= '0' && r <= '9'):
		return p.parseNumber()
	default:
		// try keywords
		rest := string(p.src[p.pos:])
		for _, kw := range []struct {
			w string
			v interface{}
		}{{"true", true}, {"false", false}, {"null", nil}, {"NaN", "nan"}, {"Infinity", "inf"}} {
			if strings.HasPrefix(rest, kw.w) {
				for i := 0; i < len(kw.w); i++ {
					p.advance()
				}
				return kw.v, nil
			}
		}
		return nil, p.errAt(expectedValue)
	}
}

func (p *parser) parseString() (string, error) {
	quote := p.advance()
	var sb strings.Builder
	for p.pos < len(p.src) {
		r := p.advance()
		if r == quote {
			return sb.String(), nil
		}
		if r == '\\' {
			if p.pos >= len(p.src) {
				break
			}
			e := p.advance()
			switch e {
			case 'n':
				sb.WriteRune('\n')
			case 't':
				sb.WriteRune('\t')
			case 'r':
				sb.WriteRune('\r')
			case 'b':
				sb.WriteRune('\b')
			case 'f':
				sb.WriteRune('\f')
			case 'v':
				sb.WriteRune('\v')
			case '0':
				sb.WriteRune(0)
			case '\n':
				// line continuation
			case 'x':
				if p.pos+2 <= len(p.src) {
					if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+2]), 16, 32); err == nil {
						sb.WriteRune(rune(v))
						p.pos += 2
						p.col += 2
