					}
				}
				sb.WriteRune('x')
			case 'u':
				if p.pos+4 <= len(p.src) {
					if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+4]), 16, 32); err == nil {
						sb.WriteRune(rune(v))
						p.pos += 4
						p.col += 4
						continue
					}
				}
				sb.WriteRune('u')
			default:
				sb.WriteRune(e)
			}
			continue
		}
		if r == '\n' {
			return "", p.errAt("expected char_literal")
		}
		sb.WriteRune(r)
	}
	return "", p.errAt("expected char_literal")
}

func (p *parser) parseNumber() (interface{}, error) {
	start := p.pos
	if p.peek() == '-' || p.peek() == '+' {
		p.advance()
	}
	for p.pos < len(p.src) {
