			p.advance()
			continue
		}
		break
	}
	txt := string(p.src[start:p.pos])
	if v, err := strconv.ParseFloat(txt, 64); err == nil {
		return v, nil
	}
	return nil, p.errAt(expectedValue)
}

func (p *parser) parseIdent() (string, error) {
	start := p.pos
	for p.pos < len(p.src) {
		r := p.peek()
		if r == '_' || r == '$' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			(r >= 0x80 && r <= 0xFFFF) {
			p.advance()
			continue
		}
		break
	}
	if p.pos == start {
		return "", p.errAt("expected identifier or string")
	}
	return string(p.src[start:p.pos]), nil
}

func (p *parser) parseObject() (map[string]interface{}, error) {
	p.advance() // {
	out := map[string]interface{}{}
	p.skipWs()
	if p.peek() == '}' {
		p.advance()
		return out, nil
	}
	for {
		p.skipWs()
		if p.pos >= len(p.src) {
			return nil, p.errAt("expected identifier or string")
		}
		var key string
		if p.peek() == '"' || p.peek() == '\'' {
			s, err := p.parseString()
			if err != nil {
				return nil, err
			}
			key = s
		} else {
			s, err := p.parseIdent()
			if err != nil {
				return nil, err
			}
			key = s
		}
		p.skipWs()
		if p.peek() != ':' {
			return nil, p.errAt("expected ':'")
		}
		p.advance()
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out[key] = v
		p.skipWs()
		if p.peek() == ',' {
			p.advance()
			p.skipWs()
			if p.peek() == '}' {
				p.advance()
				return out, nil
			}
			continue
		}
		if p.peek() == '}' {
			p.advance()
			return out, nil
		}
		if p.pos >= len(p.src) {
			return nil, p.errAt("expected ',' or '}'")
		}
		return nil, p.errAt("expected ',' or '}'")
	}
}

func (p *parser) parseArray() ([]interface{}, error) {
	p.advance()
	out := []interface{}{}
	p.skipWs()
	if p.peek() == ']' {
		p.advance()
		return out, nil
	}
	for {
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out = append(out, v)
