	for p.pos < len(p.src) {
		r := p.peek()
		if r == ' ' || r == '\t' || r == '\n' || r == '\r' || r == '\f' || r == '\v' {
			p.advance()
			continue
		}
		if r == '/' && p.at(1) == '/' {
			for p.pos < len(p.src) && p.peek() != '\n' {
				p.advance()
			}
			continue
		}
		if r == '/' && p.at(1) == '*' {
			p.advance()
			p.advance()
			for p.pos < len(p.src) {
				if p.peek() == '*' && p.at(1) == '/' {
					p.advance()
					p.advance()
					break
				}
				p.advance()
			}
			continue
		}
		break
	}
}

func (p *parser) errAt(msg string) error {
	return &json5Error{line: p.line, col: p.col, msg: msg}
}

const expectedValue = "expected array, boolean, null, number, object, or string"

func (p *parser) parseValue() (interface{}, error) {
	p.skipWs()
	if p.pos >= len(p.src) {
		return nil, p.errAt(expectedValue)
	}
	switch r := p.peek(); {
	case r == '{':
		return p.parseObject()
	case r == '[':
		return p.parseArray()
	case r == '"' || r == '\'':
		s, err := p.parseString()
		if err != nil {
			return nil, err
		}
		return s, nil
	case r == '-' || (r >= '0' && r <= '9'):
		return p.parseNumber()
	default:
		// try keywords
		rest := string(p.src[p.pos:])
		for _, kw := range []struct {
			w string
			v interface{}
		}{{"true", true}, {"false", false}, {"null", nil}, {"NaN", "nan"}, {"Infinity", "inf"}} {
			if strings.HasPrefix(rest, kw.w) {
				for i := 0; i < len(kw.w); i++ {
					p.advance()
				}
				return kw.v, nil
			}
		}
		return nil, p.errAt(expectedValue)
	}
}

func (p *parser) parseString() (string, error) {
	quote := p.advance()
	var sb strings.Builder
	for p.pos < len(p.src) {
		r := p.advance()
		if r == quote {
			return sb.String(), nil
		}
		if r == '\\' {
			if p.pos >= len(p.src) {
				break
			}
			e := p.advance()
			switch e {
			case 'n':
				sb.WriteRune('\n')
			case 't':
				sb.WriteRune('\t')
			case 'r':
				sb.WriteRune('\r')
			case 'b':
				sb.WriteRune('\b')
			case 'f':
				sb.WriteRune('\f')
			case 'v':
				sb.WriteRune('\v')
			case '0':
				sb.WriteRune(0)
			case '\n':
				// line continuation
			case 'x':
				if p.pos+2 <= len(p.src) {
					if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+2]), 16, 32); err == nil {
						sb.WriteRune(rune(v))
						p.pos += 2
						p.col += 2
						continue
					}
				}
				sb.WriteRune('x')
			case 'u':
				if p.pos+4 <= len(p.src) {
					if v, err := strconv.ParseUint(string(p.src[p.pos:p.pos+4]), 16, 32); err == nil {
						sb.WriteRune(rune(v))
						p.pos += 4
						p.col += 4
						continue
					}
				}
				sb.WriteRune('u')
			default:
				sb.WriteRune(e)
			}
			continue
		}
		if r == '\n' {
			return "", p.errAt("expected char_literal")
		}
		sb.WriteRune(r)
	}
	return "", p.errAt("expected char_literal")
}

func (p *parser) parseNumber() (interface{}, error) {
	start := p.pos
	if p.peek() == '-' || p.peek() == '+' {
		p.advance()
	}
	for p.pos < len(p.src) {
		r := p.peek()
		if (r >= '0' && r <= '9') || r == '.' || r == 'e' || r == 'E' || r == '+' || r == '-' || r == 'x' || r == 'X' ||
			(r >= 'a' && r <= 'f') || (r >= 'A' && r <= 'F') {
			p.advance()
			continue
		}
		break
	}
	txt := string(p.src[start:p.pos])
	if v, err := strconv.ParseFloat(txt, 64); err == nil {
		return v, nil
	}
	return nil, p.errAt(expectedValue)
}

func (p *parser) parseIdent() (string, error) {
	start := p.pos
	for p.pos < len(p.src) {
		r := p.peek()
		if r == '_' || r == '$' || (r >= 'a' && r <= 'z') || (r >= 'A' && r <= 'Z') || (r >= '0' && r <= '9') ||
			(r >= 0x80 && r <= 0xFFFF) {
			p.advance()
			continue
		}
		break
	}
	if p.pos == start {
		return "", p.errAt("expected identifier or string")
	}
	return string(p.src[start:p.pos]), nil
}

func (p *parser) parseObject() (map[string]interface{}, error) {
	p.advance() // {
	out := map[string]interface{}{}
	p.skipWs()
	if p.peek() == '}' {
		p.advance()
		return out, nil
	}
	for {
		p.skipWs()
		if p.pos >= len(p.src) {
			return nil, p.errAt("expected identifier or string")
		}
		var key string
		if p.peek() == '"' || p.peek() == '\'' {
			s, err := p.parseString()
			if err != nil {
				return nil, err
			}
			key = s
		} else {
			s, err := p.parseIdent()
			if err != nil {
				return nil, err
			}
			key = s
		}
		p.skipWs()
		if p.peek() != ':' {
			return nil, p.errAt("expected ':'")
		}
		p.advance()
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out[key] = v
		p.skipWs()
		if p.peek() == ',' {
			p.advance()
			p.skipWs()
			if p.peek() == '}' {
				p.advance()
				return out, nil
			}
			continue
		}
		if p.peek() == '}' {
			p.advance()
			return out, nil
		}
		if p.pos >= len(p.src) {
			return nil, p.errAt("expected ',' or '}'")
		}
		return nil, p.errAt("expected ',' or '}'")
	}
}

func (p *parser) parseArray() ([]interface{}, error) {
	p.advance()
	out := []interface{}{}
	p.skipWs()
	if p.peek() == ']' {
		p.advance()
		return out, nil
	}
	for {
		v, err := p.parseValue()
		if err != nil {
			return nil, err
		}
		out = append(out, v)
		p.skipWs()
		if p.peek() == ',' {
			p.advance()
			p.skipWs()
			if p.peek() == ']' {
				p.advance()
				return out, nil
			}
			continue
		}
		if p.peek() == ']' {
			p.advance()
			return out, nil
		}
		return nil, p.errAt("expected ',' or ']'")
	}
}

func describeJSON(v interface{}) string {
	switch t := v.(type) {
	case string:
		return fmt.Sprintf("string %q", t)
	case float64:
		if t == float64(int64(t)) {
			return fmt.Sprintf("integer `%d`", int64(t))
		}
		return fmt.Sprintf("floating point `%v`", t)
	case bool:
		return fmt.Sprintf("boolean `%v`", t)
	case nil:
		return "null"
	case []interface{}:
		return "sequence"
	case map[string]interface{}:
		return "map"
	}
	return "value"
}

// LoadConfig reads and parses the configuration file.
func LoadConfig() (map[string]Action, error) {
	bindings := defaultKeybindings()
	path := configPath()
	data, err := os.ReadFile(path)
	if err != nil {
		if os.IsNotExist(err) {
			return bindings, nil
		}
		return nil, err
	}
	src := string(data)
	p := &parser{src: []rune(src), line: 1, col: 1}
	v, perr := p.parseValue()
	if perr != nil {
		je, _ := perr.(*json5Error)
		msg := ""
		if je != nil {
			msg = pestReport(src, je.line, je.col, je.msg, relativePath(path))
		} else {
			msg = perr.Error()
		}
		return nil, fmt.Errorf("%s", msg)
	}
	p.skipWs()
	if p.pos < len(p.src) {
		msg := pestReport(src, p.line, p.col, "expected EOI", relativePath(path))
		return nil, fmt.Errorf("%s", msg)
	}
	obj, ok := v.(map[string]interface{})
	if !ok {
		return nil, fmt.Errorf("invalid type: %s, expected a map in %s in %s",
			describeJSON(v), relativePath(path), relativePath(path))
	}
	if raw, present := obj["keybindings"]; present {
		kb, ok := raw.(map[string]interface{})
		if !ok {
			return nil, fmt.Errorf("invalid type: %s, expected a map", describeJSON(raw))
		}
		for k, val := range kb {
			s, ok := val.(string)
			if !ok {
				return nil, fmt.Errorf("Unknown Action variant: %s", describeJSON(val))
			}
			act, err := ActionFromName(s)
			if err != nil {
				return nil, err
			}
			bindings[normalizeKeyName(k)] = act
		}
	}
	return bindings, nil
}

// normalizeKeyName lowercases and strips the angle brackets of a key name.
func normalizeKeyName(k string) string {
	s := strings.TrimSpace(k)
	s = strings.TrimPrefix(s, "<")
	s = strings.TrimSuffix(s, ">")
	return strings.ToLower(s)
}
