// pestReport builds a pest-style error report.
func pestReport(src string, line, col int, msg, path string) string {
	lines := strings.Split(src, "\n")
	var srcLine string
	if line-1 >= 0 && line-1 < len(lines) {
		srcLine = strings.TrimRight(lines[line-1], "\r")
	}
	numStr := strconv.Itoa(line)
	pad := strings.Repeat(" ", len(numStr))
	caretPad := strings.Repeat(" ", maxInt(0, col-1))
	var sb strings.Builder
	fmt.Fprintf(&sb, " --> %d:%d\n", line, col)
	fmt.Fprintf(&sb, "%s |\n", pad)
	fmt.Fprintf(&sb, "%s | %s\n", numStr, srcLine)
	fmt.Fprintf(&sb, "%s | %s^---\n", pad, caretPad)
	fmt.Fprintf(&sb, "%s |\n", pad)
	fmt.Fprintf(&sb, "  = %s in %s", msg, path)
	return sb.String()
}

