			if i == m.Row-globalOffset(a, idx) {
				continue
			}
			out = append(out, l)
		}
		lines = out
	} else {
		mi := NewMatcher(a.searchMode, a.search.Text)
		off := globalOffset(a, idx)
		lines[m.Row-off] = replaceOne(lines[m.Row-off], mi, a.replaceMode, a.replace.Text, m.Start, m.End)
	}
