	a.startSearch()
}

// deleteFile removes the selected file from the replacement process.
func (a *App) deleteFile() {
	if a.sel < 0 || a.sel >= len(a.results) {
		return
	}
	a.results = append(a.results[:a.sel], a.results[a.sel+1:]...)
	if len(a.results) == 0 {
		a.sel = -1
		a.curMatch = -1
		a.prevRows = nil
		a.prevMatches = nil
		a.groups = nil
		return
	}
	if a.sel >= len(a.results) {
		a.sel = len(a.results) - 1
	}
	a.curMatch = -1
	a.rebuildPreview()
	a.updateScroll()
}

// deleteLine removes the current line from the replacement process.
func (a *App) deleteLine() {
	m := a.selectedMatch()
	if m == nil {
		return
	}
	idx := a.sel
	off := globalOffset(a, idx)
	res := &a.results[idx]
	// remove the match from the result's match list
	lineIdx := m.Row - off
	var nm []Match
	for _, mm := range res.Matches {
		if mm.Line == lineIdx {
			continue
		}
		nm = append(nm, mm)
	}
	res.Matches = nm
	res.Count = len(nm)
	a.rebuildPreview()
	a.recomputeCounts()
	if a.curMatch >= a.selMatchCount() {
		a.curMatch = a.selMatchCount() - 1
	}
	a.updateScroll()
}

func (a *App) recomputeCounts() {
	off := 0
	for i := range a.results {
		a.results[i].Count = len(a.results[i].Matches)
		_ = off
	}
}

// refresh re-walks the project and re-runs the search.
func (a *App) refresh() {
	files, _ := Walk(a.root)
	a.files = files
	a.startSearch()
}
