func (in *Input) Insert(s string) {
	r := []rune(in.Text)
	c := in.Cursor
	var sb strings.Builder
	sb.WriteString(string(r[:c]))
	sb.WriteString(s)
	sb.WriteString(string(r[c:]))
	in.Text = sb.String()
	in.Cursor = c + len([]rune(s))
}

func (in *Input) Backspace() {
	if in.Cursor == 0 {
		return
	}
	r := []rune(in.Text)
	in.Text = string(r[:in.Cursor-1]) + string(r[in.Cursor:])
	in.Cursor--
}

func (in *Input) Delete() {
	r := []rune(in.Text)
	if in.Cursor >= len(r) {
		return
	}
	in.Text = string(r[:in.Cursor]) + string(r[in.Cursor+1:])
