// ---------- layout ----------

func leftWidth(w int) int { return (w*30 + 50) / 100 }

// splitShrink distributes total between two desired sizes, giving the surplus
// to the first block (mimicking the layout solver's behaviour).
func splitShrink(total, a, b int) (int, int) {
	if total <= 0 {
		return 0, 0
	}
	if total >= a+b {
		return a, total - a - b
	}
	first := (total*a + (a + b) - 1) / (a + b)
	if first > total {
		first = total
	}
	return first, total - first
}

func (a *App) layout() (search, replace, list, preview Area, helpY int) {
	w := a.screen.buf.W
	h := a.screen.buf.H
	lw := leftWidth(w)
	helpY = h - 1
	mainH := h - 1
	if mainH < 0 {
		mainH = 0
	}
	sH, rH := splitShrink(mainH, 3, 3)
	rest := mainH - sH - rH
	if rest < 0 {
		rest = 0
	}
	search = Area{X: 0, Y: 0, W: lw, H: sH}
	replace = Area{X: 0, Y: sH, W: lw, H: rH}
	list = Area{X: 0, Y: sH + rH, W: lw, H: rest}
	preview = Area{X: lw, Y: 0, W: w - lw, H: mainH}
	return
}

// ---------- rendering ----------

var (
	colWhite      = Style{Fg: 15, Bg: -1}
	colFocus      = Style{Fg: 2, Bg: -1, Bold: true}
	colPreview    = Style{Fg: 2, Bg: -1}
	colYellow     = Style{Fg: 3, Bg: -1}
	colBlue       = Style{Fg: 4, Bg: -1}
	colGray       = Style{Fg: 8, Bg: -1}
	colLightGreen = Style{Fg: 10, Bg: -1}
	colSelected   = Style{Fg: 15, Bg: 4}
)

func (a *App) helpText() string {
	switch a.focus {
	case FocusSearch:
		return "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
	case FocusReplace:
		return "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
	case FocusResultList:
		return "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"
	case FocusPreview:
		return "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>"
	}
	if a.helpOpen {
		return "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
	}
	return "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
}

// wrapFirstLine returns the first line of text word-wrapped to width.
func wrapFirstLine(text string, width int) string {
	if width <= 0 {
		return ""
	}
	words := strings.Fields(text)
	var sb strings.Builder
	cur := 0
	first := true
	for _, wd := range words {
		add := len([]rune(wd))
		if !first {
			add++
		}
		if cur+add > width {
			break
		}
		if !first {
			sb.WriteString(" ")
		}
		sb.WriteString(wd)
		cur += add
		first = false
	}
	return sb.String()
}

func (a *App) draw() {
	buf := a.screen.Buf()
	buf.Reset()
	search, replace, list, preview, helpY := a.layout()
	// search block
	buf.DrawBlock(search, Block{Title: "Search", Tabs: searchModeNames, TabIdx: a.searchMode,
		Style: a.blockStyle(FocusSearch)})
	a.drawInput(buf, search.Inner(), a.search, "", a.focus == FocusSearch)
	// replace block
	rTabs := replaceModeNames
	ph := ""
	if a.replaceMode == ReplaceDeleteLine {
		ph = "[Entire line will be deleted]"
	}
	buf.DrawBlock(replace, Block{Title: "Replace", Tabs: rTabs, TabIdx: a.replaceMode,
		Style: a.blockStyle(FocusReplace)})
	a.drawInput(buf, replace.Inner(), a.replace, ph, a.focus == FocusReplace)
	// result list
	buf.DrawBlock(list, Block{Title: "Result List", Style: a.blockStyle(FocusResultList)})
	a.drawResultList(buf, list.Inner())
	// preview
	buf.DrawBlock(preview, Block{Title: "Preview", Style: a.blockStyle(FocusPreview)})
	a.drawPreview(buf, preview.Inner())
	// help line
	hw := a.screen.buf.W - leftWidth(a.screen.buf.W)
	a.drawHelpLine(buf, helpY, hw)
	if a.helpOpen {
		a.drawHelpDialog(buf)
	}
	if a.needsEnt {
		a.drawNotification(buf)
	}
	// cursor
	var cur *CursorPos
	switch a.focus {
	case FocusSearch:
		in := a.search
		inner := search.Inner()
		start := in.Scroll
		if in.Cursor < start {
			start = in.Cursor
		}
		if in.Cursor >= start+inner.W {
			start = in.Cursor - inner.W + 1
		}
		cur = &CursorPos{X: inner.X + (in.Cursor - start), Y: inner.Y}
	case FocusReplace:
		in := a.replace
		inner := replace.Inner()
		start := in.Scroll
		if in.Cursor < start {
			start = in.Cursor
		}
		if in.Cursor >= start+inner.W {
			start = in.Cursor - inner.W + 1
		}
		cur = &CursorPos{X: inner.X + (in.Cursor - start), Y: inner.Y}
	}
	a.screen.Draw(cur)
}

func (a *App) blockStyle(f Focus) Style {
	if a.focus == f {
		if f == FocusPreview {
			return colPreview
		}
		return colFocus
	}
	if f == FocusPreview {
		return defStyle
	}
	return colWhite
}

func (b *Buffer) drawInput(a Area, in *Input, placeholder string, focused bool) {
	if a.H <= 0 || a.W <= 0 {
		return
	}
	text := in.Text
	if text == "" && placeholder != "" {
		b.WriteRunes(a.X, a.Y, placeholder, colGray)
		return
	}
	runes := []rune(text)
	start := in.Scroll
	if in.Cursor < start {
		start = in.Cursor
	}
	if in.Cursor >= start+a.W {
		start = in.Cursor - a.W + 1
	}
	if start < 0 {
		start = 0
	}
	end := start + a.W
	if end > len(runes) {
		end = len(runes)
	}
	if end > start {
		b.WriteRunes(a.X, a.Y, string(runes[start:end]), colWhite)
	}
}

func (b *Buffer) drawResultList(a Area) {
	if a.H <= 0 {
		return
	}
	// the visible window of items
	off := a.resultOffset
	if a.sel >= 0 {
		if a.sel < off {
			off = a.sel
		} else if a.sel >= off+a.H {
			off = a.sel - a.H + 1
		}
	}
	n := len(a.results)
	for i := 0; i < a.H; i++ {
		idx := off + i
		if idx >= n {
			break
		}
		r := a.results[idx]
		st := colWhite
		if idx == a.sel {
			st = colSelected
		}
		b.SetStyle(Area{X: a.X, Y: a.Y + i, W: a.W, H: 1}, st)
		txt := fmt.Sprintf("%s (%d)", r.Path, r.Count)
		b.WriteRunes(a.X, a.Y+i, txt, st)
		// the count is highlighted
		txtRunes := []rune(txt)
		pathLen := len([]rune(r.Path))
		cnt := fmt.Sprintf("%d", r.Count)
		cntStyle := Style{Fg: 3, Bg: st.Bg}
		base := a.X + pathLen + 2
		for j := 0; j < len(cnt); j++ {
			if base+j < a.X+a.W {
				b.set(base+j, a.Y+i, rune(cnt[j]), cntStyle)
			}
		}
	}
