	a.drawHelpLine(buf, helpY, hw)
	if a.helpOpen {
		a.drawHelpDialog(buf)
	}
	if a.needsEnt {
		a.drawNotification(buf)
	}
	// cursor
	var cur *CursorPos
	switch a.focus {
	case FocusSearch:
		in := a.search
		inner := search.Inner()
		start := in.Scroll
		if in.Cursor < start {
			start = in.Cursor
		}
		if in.Cursor >= start+inner.W {
