	list = Area{X: 0, Y: sH + rH, W: lw, H: rest}
	preview = Area{X: lw, Y: 0, W: w - lw, H: mainH}
	return
}

// ---------- rendering ----------

var (
	colWhite      = Style{Fg: 15, Bg: -1}
	colFocus      = Style{Fg: 2, Bg: -1, Bold: true}
	colPreview    = Style{Fg: 2, Bg: -1}
	colYellow     = Style{Fg: 3, Bg: -1}
	colBlue       = Style{Fg: 4, Bg: -1}
	colGray       = Style{Fg: 8, Bg: -1}
	colLightGreen = Style{Fg: 10, Bg: -1}
	colSelected   = Style{Fg: 15, Bg: 4}
)

func (a *App) helpText() string {
	switch a.focus {
	case FocusSearch:
		return "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
	case FocusReplace:
		return "Help: <Ctrl-b> | Replace: <C-o> | Toggle replace mode: <Ctrl-n>"
	case FocusResultList:
		return "Help: <Ctrl-b> | Open File: <Enter> | Replace File: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete file: <d>"
	case FocusPreview:
		return "Help: <Ctrl-b> | Back to list: <Enter> | Replace Line: <r> | Next: <j> | Previous: <k> | Top: <g> | Bottom: <G> | Delete line: <d>"
	}
	if a.helpOpen {
		return "Close Help: <Esc> | Next Tab: <Right> | Previous Tab: <Left>"
	}
	return "Help: <Ctrl-b> | Search: <Enter> | Toggle search mode: <Ctrl-n>"
}

// wrapFirstLine returns the first line of text word-wrapped to width.
func wrapFirstLine(text string, width int) string {
	if width <= 0 {
		return ""
	}
	words := strings.Fields(text)
	var sb strings.Builder
	cur := 0
	first := true
	for _, wd := range words {
		add := len([]rune(wd))
		if !first {
			add++
		}
		if cur+add > width {
			break
		}
		if !first {
			sb.WriteString(" ")
		}
		sb.WriteString(wd)
		cur += add
		first = false
	}
	return sb.String()
}

func (a *App) draw() {
	buf := a.screen.Buf()
	buf.Reset()
	search, replace, list, preview, helpY := a.layout()
	// search block
	buf.DrawBlock(search, Block{Title: "Search", Tabs: searchModeNames, TabIdx: a.searchMode,
		Style: a.blockStyle(FocusSearch)})
	a.drawInput(buf, search.Inner(), a.search, "", a.focus == FocusSearch)
	// replace block
	rTabs := replaceModeNames
	ph := ""
	if a.replaceMode == ReplaceDeleteLine {
		ph = "[Entire line will be deleted]"
	}
	buf.DrawBlock(replace, Block{Title: "Replace", Tabs: rTabs, TabIdx: a.replaceMode,
		Style: a.blockStyle(FocusReplace)})
	a.drawInput(buf, replace.Inner(), a.replace, ph, a.focus == FocusReplace)
	// result list
	buf.DrawBlock(list, Block{Title: "Result List", Style: a.blockStyle(FocusResultList)})
	a.drawResultList(buf, list.Inner())
	// preview
	buf.DrawBlock(preview, Block{Title: "Preview", Style: a.blockStyle(FocusPreview)})
	a.drawPreview(buf, preview.Inner())
	// help line
	hw := a.screen.buf.W - leftWidth(a.screen.buf.W)
	a.drawHelpLine(buf, helpY, hw)
	if a.helpOpen {
		a.drawHelpDialog(buf)
	}
	if a.needsEnt {
		a.drawNotification(buf)
	}
	// cursor
	var cur *CursorPos
	switch a.focus {
	case FocusSearch:
		in := a.search
		inner := search.Inner()
		start := in.Scroll
		if in.Cursor < start {
			start = in.Cursor
		}
		if in.Cursor >= start+inner.W {
			start = in.Cursor - inner.W + 1
		}
		cur = &CursorPos{X: inner.X + (in.Cursor - start), Y: inner.Y}
	case FocusReplace:
		in := a.replace
		inner := replace.Inner()
		start := in.Scroll
		if in.Cursor < start {
			start = in.Cursor
		}
		if in.Cursor >= start+inner.W {
			start = in.Cursor - inner.W + 1
		}
		cur = &CursorPos{X: inner.X + (in.Cursor - start), Y: inner.Y}
	}
	a.screen.Draw(cur)
}

func (a *App) blockStyle(f Focus) Style {
	if a.focus == f {
		if f == FocusPreview {
			return colPreview
		}
		return colFocus
	}
	if f == FocusPreview {
		return defStyle
	}
	return colWhite
}

func (b *Buffer) drawInput(a Area, in *Input, placeholder string, focused bool) {
	if a.H <= 0 || a.W <= 0 {
		return
	}
	text := in.Text
	if text == "" && placeholder != "" {
		b.WriteRunes(a.X, a.Y, placeholder, colGray)
		return
	}
	runes := []rune(text)
	start := in.Scroll
	if in.Cursor < start {
		start = in.Cursor
	}
	if in.Cursor >= start+a.W {
		start = in.Cursor - a.W + 1
	}
	if start < 0 {
		start = 0
	}
	end := start + a.W
	if end > len(runes) {
		end = len(runes)
	}
	if end > start {
		b.WriteRunes(a.X, a.Y, string(runes[start:end]), colWhite)
	}
}

func (b *Buffer) drawResultList(a Area) {
	if a.H <= 0 {
		return
	}
	// the visible window of items
	off := a.resultOffset
	if a.sel >= 0 {
		if a.sel < off {
			off = a.sel
		} else if a.sel >= off+a.H {
			off = a.sel - a.H + 1
		}
	}
	n := len(a.results)
	for i := 0; i < a.H; i++ {
		idx := off + i
		if idx >= n {
			break
		}
		r := a.results[idx]
		st := colWhite
		if idx == a.sel {
			st = colSelected
		}
		b.SetStyle(Area{X: a.X, Y: a.Y + i, W: a.W, H: 1}, st)
		txt := fmt.Sprintf("%s (%d)", r.Path, r.Count)
		b.WriteRunes(a.X, a.Y+i, txt, st)
		// the count is highlighted
		txtRunes := []rune(txt)
		pathLen := len([]rune(r.Path))
		cnt := fmt.Sprintf("%d", r.Count)
		cntStyle := Style{Fg: 3, Bg: st.Bg}
		base := a.X + pathLen + 2
		for j := 0; j < len(cnt); j++ {
			if base+j < a.X+a.W {
				b.set(base+j, a.Y+i, rune(cnt[j]), cntStyle)
			}
		}
	}
}

func (a *App) drawHelpLine(b *Buffer, y, width int) {
	if y < 0 || y >= b.H || width <= 0 {
		return
	}
	txt := wrapFirstLine(a.helpText(), width)
	if txt == "" {
		return
	}
	b.WriteRunes(0, y, txt, colBlue)
}

func (a *App) drawPreview(buf *Buffer, a Area) {
	if a.H <= 0 || a.W <= 0 {
		return
	}
	if a.sel < 0 || len(a.groups) == 0 {
		return
	}
	// build the flat row list
	type pr struct {
		kind   int // 0 = text, 1 = separator
		row    int
		gi     int
		offset int // offset of this row within its group
	}
	var rows []pr
	for gi, g := range a.groups {
		for r := g.Start; r <= g.End; r++ {
			rows = append(rows, pr{kind: 0, row: r, gi: gi, offset: r - g.Start})
		}
		rows = append(rows, pr{kind: 1, gi: gi})
	}
	total := len(rows)
	// scroll handling
	winH := a.H
	off := a.scroll
	// find the content row of the current match
	var curRow int
	hasCur := false
	if a.curMatch >= 0 {
		for i, r := range rows {
			if r.kind == 0 && r.gi == a.curMatch && r.row == a.groups[a.curMatch].Row {
				curRow = i
				hasCur = true
				break
			}
		}
	}
	if hasCur {
		if curRow < off {
			off = curRow - 4
			if off < 0 {
				off = 0
			}
		} else if curRow >= off+winH-5 {
			off = curRow - (winH - 5)
		}
		maxOff := total - a.screen.buf.H
		if maxOff < 0 {
			maxOff = 0
		}
		if off > maxOff {
			off = maxOff
		}
	}
	a.scroll = off
	sepStyle := colGray
	if hasCur {
		sepStyle = colYellow
	}
	for i := 0; i < winH; i++ {
		ri := off + i
		if ri >= total {
			break
		}
		r := rows[ri]
		y := a.Y + i
		if r.kind == 1 {
			b.SetStyle(Area{X: a.X, Y: y, W: a.W, H: 1}, defStyle)
			dashes := strings.Repeat("-", a.W-2)
			b.WriteRunes(a.X, y, dashes, sepStyle)
			continue
		}
		g := a.groups[r.gi]
		text := a.prevRows[r.row]
		isMatchRow := r.row == g.Row
		isCur := hasCur && r.gi == a.curMatch
		num := r.row - (g.Row - g.FileLine)
		if num < 0 {
			num = 0
		}
		numTxt := fmt.Sprintf("%4d ", num)
		if isCur {
			b.SetStyle(Area{X: a.X, Y: y, W: a.W, H: 1}, Style{Fg: 15, Bold: true})
			b.WriteRunes(a.X, y, "> "+numTxt, Style{Fg: 15, Bold: true})
		} else {
			b.SetStyle(Area{X: a.X, Y: y, W: a.W, H: 1}, defStyle)
			b.WriteRunes(a.X, y, "  ", defStyle)
			numStyle := colBlue
			if isMatchRow {
				numStyle = colLightGreen
			}
			b.WriteRunes(a.X+2, y, numTxt, numStyle)
		}
		tx := a.X + 7
		avail := a.W - 7
		if avail <= 0 {
			continue
		}
		if isMatchRow {
			a.drawMatchLine(buf, tx, y, avail, text, g, isCur)
		} else {
			b.WriteRunes(tx, y, text, colGray)
		}
	}
}

// drawMatchLine renders a line with its matches highlighted/replaced.
func (a *App) drawMatchLine(buf *Buffer, x, y, avail int, text string, g Group, isCur bool) {
	res := a.results[a.sel]
	var ms []Match
	for _, m := range res.Matches {
		if m.Line == g.FileLine-1 {
			ms = append(ms, m)
		}
	}
	// sort by start
	for i := 1; i < len(ms); i++ {
		for j := i; j > 0 && ms[j].Start < ms[j-1].Start; j-- {
			ms[j], ms[j-1] = ms[j-1], ms[j]
		}
	}
	repl := a.replace.Text
	mode := a.replaceMode
	runes := []rune(text)
	// byte offset to rune offset helper
	byteToRune := func(b int) int {
		if b >= len(text) {
			return len(runes)
		}
		return len([]rune(text[:b]))
	}
	delLine := mode == ReplaceDeleteLine
	stMatch := Style{Fg: 15, Cross: true}
	_ = delLine
	if len(repl) == 0 && mode != ReplaceDeleteLine {
		stMatch = Style{Fg: -1, Bg: 4}
	}
	if isCur {
		stMatch.Bold = true
	}
	if delLine {
		stMatch = Style{Fg: 15, Bg: 1, Cross: true}
		if isCur {
			stMatch.Bold = true
		}
		// the whole line is struck
		lim := avail
		if len(runes) < lim {
			lim = len(runes)
		}
		if lim > 0 {
			buf.WriteRunes(x, y, string(runes[:lim]), stMatch)
		}
		return
	}
	if len(ms) == 0 {
		buf.WriteRunes(x, y, text, defStyle)
		return
	}
	cur := 0 // rune offset
	for _, m := range ms {
		s := byteToRune(m.Start)
		e := byteToRune(m.End)
		if s > cur {
			seg := string(runes[cur:s])
			if s-cur > avail {
				seg = string(runes[cur : cur+avail])
			}
			buf.WriteRunes(x+cur, y, seg, defStyle)
			avail -= s - cur
			cur = s
			if avail <= 0 {
				return
			}
		}
		width := e - s
		if width > avail {
			width = avail
		}
		if width > 0 {
			buf.WriteRunes(x+cur, y, string(runes[cur:cur+width]), stMatch)
			avail -= width
			cur += width
		}
		if avail <= 0 {
			return
		}
		rt := repl
		if mode == ReplacePreserveCase {
			rt = preserveCase(string(runes[s:e]), repl)
		}
		rRunes := []rune(rt)
		w2 := len(rRunes)
		if w2 > avail {
			w2 = avail
		}
		if w2 > 0 {
			buf.WriteRunes(x+cur, y, string(rRunes[:w2]), Style{Fg: 15, Bg: 2, Bold: isCur})
			avail -= w2
			cur += w2
		}
		if avail <= 0 {
			return
		}
	}
	if cur < len(runes) && avail > 0 {
		w := len(runes) - cur
		if w > avail {
			w = avail
		}
		buf.WriteRunes(x+cur, y, string(runes[cur:cur+w]), defStyle)
	}
}
GOEOF
echo ok"}

