// wrapLines word-wraps each line to the given width.
func wrapLines(lines []string, width int) []string {
	var out []string
	for _, l := range lines {
		if l == "" {
			out = append(out, "")
			continue
		}
		words := strings.Fields(l)
		var sb strings.Builder
		cur := 0
		first := true
		for _, wd := range words {
			add := len([]rune(wd))
			if !first {
				add++
			}
			if !first && cur+add > width {
				out = append(out, sb.String())
