			}
			if !first {
				sb.WriteString(" ")
			}
			sb.WriteString(wd)
			cur += add
			first = false
		}
		out = append(out, sb.String())
	}
	return out
}

func (a *App) helpDialogLines() [][]string {
	return [][]string{helpGlobalLines, helpNavigationLines}
}

func (a *App) drawHelpDialog(buf *Buffer) {
	w := buf.W
	h := buf.H
	dw := w
	if dw > 80 {
		dw = 80
	}
	dh := h
	if dh > 15 {
		dh = 15
	}
	x := (w - dw) / 2
	y := (h - dh) / 2
	area := Area{X: x, Y: y, W: dw, H: dh}
	// clear the area
	buf.SetStyle(area, defStyle)
	for yy := y; yy < y+dh; yy++ {
		for xx := x; xx < x+dw; xx++ {
			buf.set(xx, yy, ' ', defStyle)
		}
	}
	yel := Style{Fg: 3, Bg: -1}
	blk := Block{Title: "", Style: yel, Right: "Press 'q' to close"}
	buf.DrawBlock(area, blk)
	inner := area.Inner()
	// tabs: left aligned
	tabs := []string{" [1] Global ", " [2] Navigation "}
	var tb strings.Builder
	for i, t := range tabs {
		if i > 0 {
			tb.WriteString("─")
		}
		tb.WriteString(t)
	}
	tabLine := tb.String()
	// the active tab is green, the rest yellow
	runes := []rune(tabLine)
	// compute the style spans
	sty := make([]Style, len(runes))
	idx := 0
	for i, t := range tabs {
		tr := []rune(t)
		st := yel
		if i == a.helpTab {
			st = Style{Fg: 2, Bg: -1}
		}
		for range tr {
			sty[idx] = st
			idx++
		}
		if i > 0 {
			// the divider before this tab
			sty[idx-len(tr)-1] = yel
		}
	}
	lim := inner.W
	if lim > len(runes) {
		lim = len(runes)
	}
	for i := 0; i < lim; i++ {
		buf.set(inner.X+i, area.Y, runes[i], sty[i])
	}
	// right title (drawn before the tabs in the original; emulate by overwriting)
	rl := []rune("Press 'q' to close")
	rs := inner.Right() - len(rl)
	for i, r := range rl {
		if rs+i >= inner.X && rs+i < inner.Right() {
			buf.set(rs+i, area.Y, r, yel)
		}
	}
	// content
	allLines := a.helpDialogLines()
	// height = max over tabs of wrapped line count
	width := inner.W
	var maxLines int
	for _, tabLines := range allLines {
		n := len(wrapLines(tabLines, width))
		if n > maxLines {
			maxLines = n
		}
	}
	wrapped := wrapLines(allLines[a.helpTab], width)
	for i, l := range wrapped {
		if i >= inner.H {
			break
		}
		if l == "" {
			buf.SetStyle(Area{X: inner.X, Y: inner.Y + i, W: inner.W, H: 1}, colWhite)
			continue
		}
		buf.SetStyle(Area{X: inner.X, Y: inner.Y + i, W: inner.W, H: 1}, colWhite)
		buf.WriteRunes(inner.X, inner.Y+i, l, colWhite)
	}
}

// ---------- notification ----------

func (a *App) drawNotification(buf *Buffer) {
	w := buf.W
	h := buf.H
	x := w - 52
	y := h - 5
	ww := 51
	wh := 3
	if x < 0 || y < 0 || x+ww > w || y+wh > h {
