package main

import (
	"fmt"
	"os"
	"strings"
)

const version = "serpl 0.3.4- (2026-06-11)\n\nAuthors: Yassine Bridi <ybridi@gmail.com>\n\nConfig directory: %s\n"

const helpText = `A simple terminal UI for search and replace, ala VS Code

Usage: %s [OPTIONS]

Options:
  -p, --project-root <PATH>  Path to the project root [default: .]
  -h, --help                 Print help
  -V, --version              Print version
`

// cliError mirrors clap's error output (with colours when stderr is a tty).
type cliError struct {
	msg     string
	tip     string
	usage   string // "main" or the suggested argument
	styled  bool
}

func useColors() bool {
	term := os.Getenv("TERM")
	if term == "" || term == "dumb" {
		return false
	}
	// check whether stderr is a terminal
	return isTTY(int(os.Stderr.Fd()))
}

func bold(s string) string     { return "\x1b[1m" + s + "\x1b[0m" }
func boldUl(s string) string   { return "\x1b[1;4m" + s + "\x1b[0m" }
func redBold(s string) string  { return "\x1b[1m\x1b[31m" + s + "\x1b[0m" }
func yellow(s string) string   { return "\x1b[33m" + s + "\x1b[39m" }
func green(s string) string    { return "\x1b[32m" + s + "\x1b[39m" }

func (e *cliError) render(prog string) string {
	var sb strings.Builder
	col := useColors()
	if col {
		sb.WriteString(redBold("error:"))
	} else {
		sb.WriteString("error:")
	}
	sb.WriteString(" " + e.msg + "\n\n")
	if e.tip != "" {
		if col {
			sb.WriteString("  " + green("tip:") + " " + e.tip + "\n\n")
		} else {
			sb.WriteString("  tip: " + e.tip + "\n\n")
		}
	}
	if e.usage == "main" {
		if col {
			sb.WriteString(boldUl("Usage:") + " " + bold(prog) + " [OPTIONS]\n\n")
		} else {
			sb.WriteString("Usage: " + prog + " [OPTIONS]\n\n")
		}
	} else {
		if col {
			sb.WriteString(boldUl("Usage:") + " " + bold(prog) + " " + bold(e.usage) + "\n\n")
		} else {
			sb.WriteString("Usage: " + prog + " " + e.usage + "\n\n")
		}
	}
	if col {
		sb.WriteString("For more information, try '" + bold("--help") + "'.\n")
	} else {
		sb.WriteString("For more information, try '--help'.\n")
	}
	return sb.String()
}

// printHelp writes the help text (with colours if stderr is a tty).
func printHelp(prog string) {
	var sb strings.Builder
	col := useColors()
	sb.WriteString("A simple terminal UI for search and replace, ala VS Code\n\n")
	if col {
		sb.WriteString(boldUl("Usage:") + " " + bold(prog) + " [OPTIONS]\n\n")
		sb.WriteString(boldUl("Options:") + "\n")
		sb.WriteString("  " + bold("-p") + ", " + bold("--project-root") + " <PATH>  Path to the project root [default: .]\n")
		sb.WriteString("  " + bold("-h") + ", " + bold("--help") + "                 Print help\n")
		sb.WriteString("  " + bold("-V") + ", " + bold("--version") + "              Print version\n")
	} else {
		sb.WriteString(fmt.Sprintf(helpText, prog))
	}
	os.Stdout.WriteString(sb.String())
}

func printVersion() {
	fmt.Fprintf(os.Stdout, version, ConfigDir())
}

func progName() string {
	p := os.Args[0]
	if i := strings.LastIndexByte(p, '/'); i >= 0 {
		p = p[i+1:]
	}
	return p
}

func main() {
	prog := progName()
	args := os.Args[1:]
	var root string
	rootSet := false
	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "--help" || arg == "-h":
			printHelp(prog)
			return
		case arg == "--version" || arg == "-V":
			printVersion()
			return
		case arg == "-p" || arg == "--project-root":
			if i+1 >= len(args) || args[i+1] == "" {
				e := &cliError{msg: "a value is required for '" + yellow("--project-root <PATH>") + "' but none was supplied", usage: "none"}
				fmt.Fprint(os.Stderr, e.renderPlain(prog))
				os.Exit(2)
			}
			root = args[i+1]
			rootSet = true
			i += 2
		case strings.HasPrefix(arg, "--project-root="):
			v := strings.TrimPrefix(arg, "--project-root=")
			if v == "" {
				e := &cliError{msg: "a value is required for '" + yellow("--project-root <PATH>") + "' but none was supplied", usage: "none"}
				fmt.Fprint(os.Stderr, e.renderPlain(prog))
				os.Exit(2)
			}
			root = v
			rootSet = true
			i++
		case strings.HasPrefix(arg, "-p") && len(arg) > 2:
			root = arg[2:]
			rootSet = true
			i++
		default:
			sug := suggest(arg)
			msg := "unexpected argument '" + yellow(arg) + "' found"
			usage := "main"
			tip := ""
			if sug != "" {
				tip = "a similar argument exists: '" + green(sug) + "'"
				usage = sug
			}
			e := &cliError{msg: msg, tip: tip, usage: usage}
			fmt.Fprint(os.Stderr, e.renderPlain(prog))
			os.Exit(2)
		}
	}
	if !rootSet {
		root = "."
	}
	bind, err := LoadConfig()
	if err != nil {
		reportError(err)
		os.Exit(1)
	}
	if err := Run(root, bind); err != nil {
		reportError(err)
		os.Exit(1)
	}
}

func suggest(arg string) string {
	cands := []string{"--project-root", "--help", "--version"}
	// only long flags get suggestions
	if !strings.HasPrefix(arg, "--") {
		return ""
	}
	best := ""
	bestDist := 1 << 30
	for _, c := range cands {
		d := levenshtein(arg, c)
		if d < bestDist {
			bestDist = d
			best = c
		}
	}
	if bestDist <= (len(arg)+2)/3 && best != arg {
		return best
	}
	return ""
}

func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	dp := make([][]int, la+1)
	for i := range dp {
		dp[i] = make([]int, lb+1)
		dp[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			c := 1
			if a[i-1] == b[j-1] {
				c = 0
			}
			m := dp[i-1][j] + 1
			if v := dp[i][j-1] + 1; v < m {
				m = v
			}
			if v := dp[i-1][j-1] + c; v < m {
				m = v
			}
			dp[i][j] = m
		}
	}
	return dp[la][lb]
}

// reportError writes the eyre-style error report to stderr.
func reportError(err error) {
	msg := err.Error()
	lines := strings.Split(msg, "\n")
	var sb strings.Builder
	sb.WriteString("serpl error: Something went wrong\nError: \n")
