package main

import (
	"fmt"
	"os"
	"time"
)

// Run starts the TUI application.
func Run(root string, bind map[string]Action) error {
	term, err := NewTerminal()
	if err != nil {
		return err
	}
	defer term.DisableRaw()
	if err := term.EnableRaw(); err != nil {
		return err
	}
	scr := NewScreen(term)
	scr.EnterAltScreen()
	defer scr.LeaveAltScreen()
	app := NewApp(term, root, bind)
	app.run()
	return nil
}

func (a *App) run() {
	keyCh := make(chan KeyEvent, 64)
	go func() {
		buf := make([]byte, 4096)
		var pending []byte
		for {
			n, err := a.term.Read(buf)
			if err != nil {
				return
			}
			if n > 0 {
				pending = append(pending, buf[:n]...)
				evs, consumed := ParseKeys(pending)
				if consumed > 0 {
					pending = pending[consumed:]
				}
				for _, ev := range evs {
					keyCh <- ev
				}
			}
		}
	}()
	a.loop(keyCh)
}

func (a *App) loop(keyCh chan KeyEvent) {
	const debounce = 400 * time.Millisecond
	const tick = 40 * time.Millisecond
	var deadline time.Time
	for {
		now := time.Now()
		timeout := tick
		if a.pending {
			d := deadline.Sub(now)
			if d < timeout {
				timeout = d
			}
			if timeout < 0 {
				timeout = 0
			}
		}
		select {
		case ev, ok := <-keyCh:
			if !ok {
				return
			}
			a.lastInput = time.Now()
			cont := a.handleKey(ev)
			if !cont {
				return
			}
			if a.searchTextChanged() {
				a.pending = true
				deadline = time.Now().Add(debounce)
			}
		case r, ok := <-a.resultCh:
			if !ok {
				return
			}
			a.applyResult(r)
		case seq := <-a.doneCh:
			a.searching = false
			if seq == a.searchSeq {
				a.searched = true
				a.needsEnt = false
			}
		case <-time.After(timeout):
			if a.pending && !a.searching && !time.Now().Before(deadline) {
				a.pending = false
				if !a.large {
					a.startSearch()
				}
			}
		}
		// keep the terminal size in sync
		w, h, err := a.term.Size()
		if err == nil && (w != a.screen.buf.W || h != a.screen.buf.H) {
			a.screen.resize(w, h)
			a.screen.prev.Reset()
			a.screen.EnterAltScreen()
		}
		a.draw()
	}
}

func (a *App) searchTextChanged() bool {
	return a.search.Text != a.searchText && !a.searching && !a.needsEnt
}

func (a *App) applyResult(r FileResult) {
	a.results = append(a.results, r)
	a.rebuildPreview()
}

// handleKey processes a key event. Returns false to quit.
func (a *App) handleKey(ev KeyEvent) bool {
	// help dialog open takes precedence for its own keys
	if a.helpOpen {
		switch {
		case ev.Code == KeyEscape:
			a.helpOpen = false
			return true
		case ev.Code == KeyChar && ev.Char == 'q':
			a.helpOpen = false
			return true
		case ev.Code == KeyRight:
			a.helpTab = (a.helpTab + 1) % 2
			return true
		case ev.Code == KeyLeft:
			a.helpTab = (a.helpTab + 1) % 2
			return true
		case ev.Code == KeyEnter:
			a.helpOpen = false
			return true
		}
		// any other key closes the dialog and is processed
		a.helpOpen = false
		return a.handleKey(ev)
	}
	// config-bound actions
	key := ev.BindingKey()
	if act, ok := a.bind[key]; ok {
		switch act {
		case ActionQuit:
			return false
		case ActionSuspend:
			// not implemented in this build
			return true
		case ActionRefresh:
			if a.focus == FocusResultList || a.focus == FocusPreview {
				a.replaceFile(a.sel)
			} else if a.sel >= 0 {
				a.replaceFile(a.sel)
			}
			a.refresh()
			return true
		case ActionLoopOverTabs:
			a.loopTabs(1)
			return true
		case ActionBackLoopOverTabs:
			a.loopTabs(-1)
			return true
		case ActionProcessReplace:
			return true
		case ActionShowHelp:
			a.helpOpen = true
			a.helpTab = 0
			return true
		}
	}
	switch a.focus {
	case FocusSearch:
		return a.handleInputKey(a.search, ev)
	case FocusReplace:
		return a.handleInputKey(a.replace, ev)
	case FocusResultList:
		return a.handleListKey(ev)
	case FocusPreview:
		return a.handlePreviewKey(ev)
	}
	return true
}

func (a *App) loopTabs(dir int) {
	switch a.focus {
	case FocusSearch:
		if dir > 0 {
			a.focus = FocusReplace
		} else {
			a.focus = FocusResultList
		}
	case FocusReplace:
		if dir > 0 {
			a.focus = FocusResultList
		} else {
			a.focus = FocusSearch
		}
	case FocusResultList:
		if dir > 0 {
			a.focus = FocusSearch
		} else {
			a.focus = FocusReplace
		}
	case FocusPreview:
		a.focus = FocusResultList
	}
}

func (a *App) handleInputKey(in *Input, ev KeyEvent) bool {
	switch ev.Code {
	case KeyChar:
		if ev.Mods&ModControl != 0 {
			switch ev.Char {
			case 'u':
				in.ClearToStart()
				return true
			case 'w':
				a.deleteWord(in)
				return true
			case 'a':
				in.Home()
				return true
			case 'e':
				in.End()
				return true
			case 'n':
				a.toggleMode()
				return true
			}
			return true
		}
		in.Insert(string(ev.Char))
		return true
	case KeyBackspace:
		in.Backspace()
		return true
	case KeyDelete:
		in.Delete()
		return true
	case KeyLeft:
		in.Left()
		return true
	case KeyRight:
		in.Right()
		return true
	case KeyHome:
		in.Home()
		return true
	case KeyEnd:
		in.End()
		return true
	case KeyUp:
		return true
	case KeyDown:
		return true
	case KeyEnter:
		if a.needsEnt {
			a.needsEnt = false
			a.searched = true
			a.startSearch()
		}
		return true
	case KeyEscape:
		return true
	}
	return true
}

func (a *App) deleteWord(in *Input) {
	r := []rune(in.Text)
	i := in.Cursor
	for i > 0 && (r[i-1] == ' ' || r[i-1] == '\t') {
		i--
	}
	for i > 0 && r[i-1] != ' ' && r[i-1] != '\t' {
		i--
	}
	in.Text = string(r[:i]) + string(r[in.Cursor:])
	in.Cursor = i
}

func (a *App) toggleMode() {
	switch a.focus {
	case FocusReplace:
		a.replaceMode = (a.replaceMode + 1) % len(replaceModeNames)
		if a.replaceMode == ReplaceDeleteLine {
			a.replace.Text = ""
			a.replace.Cursor = 0
			a.replace.Scroll = 0
		}
	default:
		a.searchMode = (a.searchMode + 1) % len(searchModeNames)
	}
}

func (a *App) handleListKey(ev KeyEvent) bool {
	n := len(a.results)
	switch {
	case ev.Code == KeyDown || ev.Code == KeyRight ||
		(ev.Code == KeyChar && ev.Char == 'j'):
		if a.sel < 0 {
			if n > 0 {
				a.selectResult(0)
			}
			return true
		}
		if a.sel < n-1 {
			a.selectResult(a.sel + 1)
		}
		return true
	case ev.Code == KeyUp || ev.Code == KeyLeft ||
		(ev.Code == KeyChar && ev.Char == 'k'):
		if a.sel < 0 {
			if n > 0 {
				a.selectResult(n - 1)
			}
			return true
		}
		if a.sel > 0 {
			a.selectResult(a.sel - 1)
		}
		return true
	case ev.Code == KeyChar && ev.Char == 'g':
		if n > 0 {
			a.selectResult(0)
		}
		return true
	case ev.Code == KeyChar && ev.Char == 'G':
		if n > 0 {
			a.selectResult(n - 1)
		}
		return true
	case ev.Code == KeyChar && ev.Char == 'd':
		a.deleteFile()
		return true
	case ev.Code == KeyChar && ev.Char == 'r':
		a.replaceFile(a.sel)
		a.refresh()
		return true
	case ev.Code == KeyEnter:
		a.focus = FocusPreview
		return true
	case ev.Code == KeyChar && ev.Mods&ModControl != 0 && ev.Char == 'n':
		a.searchMode = (a.searchMode + 1) % len(searchModeNames)
		return true
	}
	return true
}

func (a *App) selectResult(idx int) {
	a.sel = idx
	a.curMatch = -1
	a.scroll = 0
	a.rebuildPreview()
}

func (a *App) handlePreviewKey(ev KeyEvent) bool {
	switch {
	case ev.Code == KeyDown || ev.Code == KeyRight ||
		(ev.Code == KeyChar && ev.Char == 'j'):
		a.nextMatch()
		return true
	case ev.Code == KeyUp || ev.Code == KeyLeft ||
		(ev.Code == KeyChar && ev.Char == 'k'):
		a.prevMatch()
		return true
	case ev.Code == KeyChar && ev.Char == 'g':
		a.firstMatch()
		return true
	case ev.Code == KeyChar && ev.Char == 'G':
		a.lastMatch()
		return true
	case ev.Code == KeyChar && ev.Char == 'd':
		a.deleteLine()
		return true
	case ev.Code == KeyChar && ev.Char == 'r':
		a.replaceLine()
		return true
	case ev.Code == KeyEnter:
		a.focus = FocusResultList
		return true
	case ev.Code == KeyChar && ev.Mods&ModControl != 0 && ev.Char == 'n':
		a.searchMode = (a.searchMode + 1) % len(searchModeNames)
		return true
	}
	return true
}

// updateScroll recomputes the preview scroll offset.
func (a *App) updateScroll() {
	// implemented during rendering (drawPreview)
	_, _, _, _, _ = fmt.Sprint()
}
