// cliError mirrors clap's error output (with colours when stderr is a tty).
type cliError struct {
	msg     string
	tip     string
	usage   string // "main" or the suggested argument
	styled  bool
}

func useColors() bool {
	term := os.Getenv("TERM")
	if term == "" || term == "dumb" {
		return false
	}
	// check whether stderr is a terminal
	return isTTY(int(os.Stderr.Fd()))
}

func bold(s string) string     { return "\x1b[1m" + s + "\x1b[0m" }
func boldUl(s string) string   { return "\x1b[1;4m" + s + "\x1b[0m" }
func redBold(s string) string  { return "\x1b[1m\x1b[31m" + s + "\x1b[0m" }
func yellow(s string) string   { return "\x1b[33m" + s + "\x1b[39m" }
func green(s string) string    { return "\x1b[32m" + s + "\x1b[39m" }

func (e *cliError) render(prog string) string {
	var sb strings.Builder
	col := useColors()
	if col {
		sb.WriteString(redBold("error:"))
	} else {
		sb.WriteString("error:")
	}
	sb.WriteString(" " + e.msg + "\n\n")
	if e.tip != "" {
		if col {
			sb.WriteString("  " + green("tip:") + " " + e.tip + "\n\n")
		} else {
			sb.WriteString("  tip: " + e.tip + "\n\n")
		}
	}
	if e.usage == "main" {
		if col {
			sb.WriteString(boldUl("Usage:") + " " + bold(prog) + " [OPTIONS]\n\n")
		} else {
			sb.WriteString("Usage: " + prog + " [OPTIONS]\n\n")
		}
	} else {
		if col {
			sb.WriteString(boldUl("Usage:") + " " + bold(prog) + " " + bold(e.usage) + "\n\n")
		} else {
			sb.WriteString("Usage: " + prog + " " + e.usage + "\n\n")
		}
	}
	if col {
		sb.WriteString("For more information, try '" + bold("--help") + "'.\n")
	} else {
		sb.WriteString("For more information, try '--help'.\n")
	}
	return sb.String()
}

