}

func main() {
	prog := progName()
	args := os.Args[1:]
	var root string
	rootSet := false
	i := 0
	for i < len(args) {
		arg := args[i]
		switch {
		case arg == "--help" || arg == "-h":
			printHelp(prog)
			return
		case arg == "--version" || arg == "-V":
			printVersion()
			return
		case arg == "-p" || arg == "--project-root":
			if i+1 >= len(args) || args[i+1] == "" {
				e := &cliError{msg: "a value is required for '" + yellow("--project-root <PATH>") + "' but none was supplied", usage: "none"}
				fmt.Fprint(os.Stderr, e.renderPlain(prog))
				os.Exit(2)
			}
			root = args[i+1]
			rootSet = true
			i += 2
		case strings.HasPrefix(arg, "--project-root="):
			v := strings.TrimPrefix(arg, "--project-root=")
			if v == "" {
				e := &cliError{msg: "a value is required for '" + yellow("--project-root <PATH>") + "' but none was supplied", usage: "none"}
				fmt.Fprint(os.Stderr, e.renderPlain(prog))
				os.Exit(2)
			}
			root = v
			rootSet = true
			i++
		case strings.HasPrefix(arg, "-p") && len(arg) > 2:
			root = arg[2:]
			rootSet = true
			i++
		default:
			sug := suggest(arg)
			msg := "unexpected argument '" + yellow(arg) + "' found"
			usage := "main"
			tip := ""
			if sug != "" {
				tip = "a similar argument exists: '" + green(sug) + "'"
				usage = sug
			}
			e := &cliError{msg: msg, tip: tip, usage: usage}
			fmt.Fprint(os.Stderr, e.renderPlain(prog))
			os.Exit(2)
		}
	}
	if !rootSet {
		root = "."
	}
	bind, err := LoadConfig()
	if err != nil {
		reportError(err)
		os.Exit(1)
	}
	if err := Run(root, bind); err != nil {
		reportError(err)
		os.Exit(1)
	}
}

func suggest(arg string) string {
	cands := []string{"--project-root", "--help", "--version"}
	// only long flags get suggestions
	if !strings.HasPrefix(arg, "--") {
		return ""
	}
	best := ""
	bestDist := 1 << 30
	for _, c := range cands {
		d := levenshtein(arg, c)
		if d < bestDist {
			bestDist = d
			best = c
		}
	}
	if bestDist <= (len(arg)+2)/3 && best != arg {
		return best
	}
	return ""
}

func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	dp := make([][]int, la+1)
	for i := range dp {
		dp[i] = make([]int, lb+1)
		dp[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			c := 1
			if a[i-1] == b[j-1] {
				c = 0
			}
			m := dp[i-1][j] + 1
			if v := dp[i][j-1] + 1; v < m {
				m = v
			}
			if v := dp[i-1][j-1] + c; v < m {
				m = v
			}
			dp[i][j] = m
		}
	}
	return dp[la][lb]
}

