}

func levenshtein(a, b string) int {
	la, lb := len(a), len(b)
	dp := make([][]int, la+1)
	for i := range dp {
		dp[i] = make([]int, lb+1)
		dp[i][0] = i
	}
	for j := 0; j <= lb; j++ {
		dp[0][j] = j
	}
	for i := 1; i <= la; i++ {
		for j := 1; j <= lb; j++ {
			c := 1
			if a[i-1] == b[j-1] {
				c = 0
			}
			m := dp[i-1][j] + 1
			if v := dp[i][j-1] + 1; v < m {
				m = v
			}
			if v := dp[i-1][j-1] + c; v < m {
				m = v
			}
			dp[i][j] = m
		}
	}
	return dp[la][lb]
}

// reportError writes the eyre-style error report to stderr.
func reportError(err error) {
	msg := err.Error()
	lines := strings.Split(msg, "\n")
	var sb strings.Builder
	sb.WriteString("serpl error: Something went wrong\nError: \n")
	for i, l := range lines {
		if i == 0 {
			sb.WriteString("   0: \x1b[91m" + l + "\n")
		} else {
			sb.WriteString("      " + l + "\n")
		}
	}
	sb.WriteString("\x1b[0m")
	os.Stderr.WriteString(sb.String())
}
